<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ApiError, apiRequest, getApiData } from '../services/api'
interface Service {service_id:number;service_name:string;category:string|null;description:string|null;price:string;duration_min:number|null;is_active:number|boolean}
const route=useRoute();const editing=ref(false);const loading=ref(false);const saving=ref(false);const error=ref('');const success=ref('');const form=reactive({service_name:'',category:'',description:'',price:'',duration_min:'30',is_active:true})
async function load(){const id=String(route.query.id||'');editing.value=!!id;if(!id)return;loading.value=true;error.value='';try{const items=await getApiData<Service[]>('/api/services');const item=items.find(x=>x.service_id===Number(id));if(!item)throw new Error('Service not found.');Object.assign(form,{service_name:item.service_name,category:item.category||'',description:item.description||'',price:String(item.price),duration_min:String(item.duration_min||30),is_active:item.is_active===true||Number(item.is_active)===1})}catch(e){error.value=e instanceof ApiError?e.message:e instanceof Error?e.message:'Could not load service.'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';success.value='';const id=String(route.query.id||'');try{await apiRequest(id?`/api/services/${id}`:'/api/services',{method:id?'PUT':'POST',body:JSON.stringify({...form,price:Number(form.price),duration_min:Number(form.duration_min)})});success.value=editing.value?'Service updated.':'Service created.';if(!id)Object.assign(form,{service_name:'',category:'',description:'',price:'',duration_min:'30',is_active:true})}catch(e){error.value=e instanceof ApiError?e.message:'Could not save service.'}finally{saving.value=false}}
onMounted(load)
watch(()=>route.query.id,load)
</script>
<template><section class="page-heading"><div><p class="eyebrow">PAGE 24 · ADMIN</p><h1>{{ editing?'Edit service':'Add service' }}</h1><p class="muted">Service details are stored in the clinic catalog.</p></div><RouterLink class="button button-quiet" to="/admin/services">Back to services</RouterLink></section><section v-if="loading" class="surface empty-state"><span class="loading-dot"/><strong>Loading service</strong></section><form v-else class="surface form-panel form-grid" @submit.prevent="save"><label class="field-full">Service name<input v-model="form.service_name" maxlength="100" required></label><label>Category<input v-model="form.category" maxlength="50"></label><label>Price (PHP)<input v-model="form.price" type="number" min="0" step="0.01" required></label><label>Duration (minutes)<input v-model="form.duration_min" type="number" min="5" max="600" required></label><label class="check-field"><input v-model="form.is_active" type="checkbox"> Active for booking</label><label class="field-full">Description<textarea v-model="form.description" rows="4" maxlength="5000"/></label><p v-if="error" class="form-error field-full">{{ error }}</p><p v-if="success" class="form-success field-full">{{ success }}</p><div class="field-full"><button class="button button-primary" :disabled="saving">{{ saving?'Saving…':'Save service' }}</button></div></form></template>
